const esc=value=>String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const number=value=>Number.isFinite(Number(value))?Number(value).toLocaleString('zh-CN'):'—';
const date=value=>value&&!Number.isNaN(Date.parse(value))?new Date(value).toLocaleString('zh-CN',{hour12:false}):'—';
const localDate=value=>value&&!Number.isNaN(Date.parse(value))?new Date(Date.parse(value)-new Date(value).getTimezoneOffset()*60000).toISOString().slice(0,16):'';
const historyNames={'user.credits.adjust':'调整科研积分','user.membership.grant':'发放会员','user.membership.update':'调整会员有效期','user.membership.revoke':'撤销会员','user.status.update':'调整账号状态','credits.adjust':'调整科研积分'};

export function mountAdminUserManagement({doc,userId,actorId,request,isCurrent,onChanged,toast}){
 const win=doc.defaultView,root=doc.querySelector('#dialog-body'),$=selector=>root.querySelector(selector),path='/admin/users/'+encodeURIComponent(userId),storageKey='paperknow-admin-command:'+actorId+':'+userId;
 let data=null,busy=false,review=null,tab='credits',loadSequence=0;
 const live=()=>isCurrent()&&root.isConnected;
 const title=()=>data?.user.name||data?.user.email||data?.user.phone||userId;
 function valid(value){return value?.user?.id===userId&&Number.isSafeInteger(value.user.version)&&value.user.version>0&&['active','banned'].includes(value.user.status)&&Number.isSafeInteger(value.credits?.available)&&Array.isArray(value.memberships)&&Array.isArray(value.membershipProducts);}
 function restoreCommand(){try{const saved=JSON.parse(win.sessionStorage.getItem(storageKey)||'null');if(saved?.payload?.commandId&&['credits','membership','status'].includes(saved.kind)&&saved.payload.version===data.user.version)return saved;}catch{}return null;}
 function persistCommand(value){try{if(value)win.sessionStorage.setItem(storageKey,JSON.stringify(value));else win.sessionStorage.removeItem(storageKey);return true;}catch{return false;}}
 function error(message){const area=$('#user-management-error');if(area){area.textContent=message;area.hidden=!message;}}
 const field=(id,label,body)=>`<div class="dialog-field"><label for="${id}">${label}</label>${body}</div>`;
 const reason=(id)=>field(id,'调整原因',`<textarea id="${id}" rows="2" maxlength="500" required placeholder="填写补偿、纠错或账号处理原因"></textarea>`);
 function history(){const rows=Array.isArray(data.history)?data.history:[];return `<details class="user-management-history"><summary>最近管理记录 <span>${rows.length} 条</span></summary><div class="user-management-scroll">${rows.length?rows.map(row=>`<article><div><b>${esc(historyNames[row.action]||row.action||'账户调整')}</b><time>${esc(date(row.createdAt||row.created_at))}</time></div><p>${esc(row.reason||row.detail?.reason||'—')}</p><small>${esc(row.actorName||row.actor_name||'管理员')}</small></article>`).join(''):'<p class="settings-note">暂无管理调整记录。</p>'}</div></details>`;}
 function memberships(){return `<div class="user-membership-list user-management-scroll">${data.memberships.length?data.memberships.map(row=>`<article><div><b>${esc(row.title)}</b><span class="badge ${row.status==='active'?'green':''}">${row.status==='active'?'有效':row.status==='revoked'?'已撤销':row.status==='scheduled'?'待生效':'已过期'}</span></div><p>${row.origin==='payment'?'购买获得':'后台发放'} · 到期 ${esc(date(row.expiresAt))}</p><small>${(row.items||[]).map(item=>esc(item.title||item.key)+' '+number(item.remaining??item.quantity)+' 次').join(' · ')||'服务额度以发放时的会员配置为准'}</small></article>`).join(''):'<p class="settings-note">该用户暂无会员。可从下方选择会员方案发放。</p>'}</div>`;}
 function render(){
  if(!live()||!data)return;
  const u=data.user,c=data.credits,protectedAccount=u.role==='admin'||u.id===actorId,grants=data.memberships.filter(row=>row.status!=='revoked');
  root.innerHTML=`<section class="user-management"><header class="user-management-heading"><div class="user-management-avatar" aria-hidden="true">${esc((u.name||'U').slice(0,1))}</div><div><h3>${esc(title())}</h3><p>${esc(u.email||u.phone||'未填写联系方式')} <span>·</span> ${u.role==='admin'?'管理员':'普通用户'}</p><small>用户 ID：${esc(u.id)}</small></div><span class="badge ${u.status==='banned'?'red':'green'}">${u.status==='banned'?'已封禁':'正常使用'}</span></header><div class="user-account-metrics"><div><span>科研积分余额</span><b>${number(c.balance)}</b></div><div><span>任务预占积分</span><b>${number(c.held)}</b></div><div><span>当前可用积分</span><b>${number(c.available)}</b></div><div><span>有效会员</span><b>${data.memberships.filter(row=>row.status==='active').length}<small> 份</small></b></div></div><div class="user-management-toolbar"><span>每次调整均记录管理员、原因和时间</span><button type="button" class="text-button" id="user-reload-detail">刷新用户资料</button></div><p id="user-management-error" class="form-error" role="alert" hidden></p><div class="user-manage-tabs" role="tablist" aria-label="用户管理项目">${[['credits','积分管理'],['membership','会员管理'],['status','账号状态']].map(([key,label])=>`<button type="button" role="tab" data-user-tab="${key}" aria-selected="${key===tab}">${label}</button>`).join('')}</div><section data-user-panel="credits" ${tab==='credits'?'':'hidden'}><div class="user-management-panel-heading"><h3>调整科研积分</h3><p>增加或扣回指定积分，已被任务预占的积分不能扣减。</p></div><form id="user-credit-form"><div class="user-management-fields">${field('user-credit-direction','调整方式','<select id="user-credit-direction"><option value="add">增加积分</option><option value="subtract">减少积分</option></select>')}${field('user-credit-amount','积分数量','<input id="user-credit-amount" type="number" min="1" max="1000000" step="1" inputmode="numeric" required placeholder="填写正整数">')}</div>${reason('user-credit-reason')}<div class="dialog-actions"><button class="button primary" type="submit">核对积分调整</button></div></form><details class="user-management-history"><summary>最近积分流水</summary><div class="user-management-scroll">${(c.ledger||[]).slice(0,20).map(row=>`<article><div><b>${esc(row.title||'科研积分')}</b><strong>${Number(row.amount)>0?'+':''}${number(row.amount)}</strong></div><p>${esc(date(row.createdAt))}</p></article>`).join('')||'<p class="settings-note">暂无积分流水。</p>'}</div></details></section><section data-user-panel="membership" ${tab==='membership'?'':'hidden'}><div class="user-management-panel-heading"><h3>会员与有效期</h3><p>发放会员、延长或缩短到期时间，也可撤销误发权益。原购买记录会保留。</p></div>${memberships()}<form id="user-membership-form"><div class="user-management-fields">${field('user-member-action','调整方式','<select id="user-member-action"><option value="grant">发放会员</option><option value="update">调整到期时间</option><option value="revoke">撤销会员</option></select>')}<div id="user-member-product-field">${field('user-member-product','会员方案',`<select id="user-member-product">${data.membershipProducts.map(row=>`<option value="${esc(row.id)}">${esc(row.title)} · ${number(row.durationDays)} 天</option>`).join('')}</select>`)}</div><div id="user-member-grant-field" hidden>${field('user-member-grant','选择已有会员',`<select id="user-member-grant">${grants.map(row=>`<option value="${esc(row.id)}">${esc(row.title)} · ${row.origin==='payment'?'购买获得':'后台发放'} · ${esc(date(row.expiresAt))}</option>`).join('')}</select>`)}</div><div id="user-member-expiry-field">${field('user-member-expiry','到期时间（本地时间，可调整）','<input id="user-member-expiry" type="datetime-local">')}</div></div><p class="settings-note" id="user-member-note"></p>${reason('user-member-reason')}<div class="dialog-actions"><button class="button primary" type="submit">核对会员调整</button></div></form></section><section data-user-panel="status" ${tab==='status'?'':'hidden'}><div class="user-management-panel-heading"><h3>账号状态</h3><p>封禁后立即退出登录并阻止再次登录；解封后用户可重新登录。</p></div>${protectedAccount?'<p class="user-protected-notice">当前管理员账号与管理员身份受到保护，不能在这里封禁。</p>':`<form id="user-status-form">${field('user-status-value','调整为',`<select id="user-status-value"><option value="active" ${u.status==='active'?'selected':''}>正常使用 / 解封</option><option value="banned" ${u.status==='banned'?'selected':''}>封禁账号</option></select>`)}${reason('user-status-reason')}<div class="dialog-actions"><button class="button danger-solid" type="submit">核对账号状态</button></div></form>`}</section><div id="user-management-review"></div>${history()}</section>`;
  root.querySelectorAll('[data-user-tab]').forEach(button=>button.onclick=()=>{tab=button.dataset.userTab;root.querySelectorAll('[data-user-tab]').forEach(node=>node.setAttribute('aria-selected',String(node===button)));root.querySelectorAll('[data-user-panel]').forEach(node=>node.hidden=node.dataset.userPanel!==tab);});
  $('#user-reload-detail').onclick=()=>{if(!busy)void load();};
  $('#user-member-action').onchange=memberFields;$('#user-member-product').onchange=()=>memberFields(true);$('#user-member-grant').onchange=()=>memberFields(true);memberFields(true);
  $('#user-credit-form').onsubmit=event=>{event.preventDefault();try{const amount=Number($('#user-credit-amount').value);if(!Number.isSafeInteger(amount)||amount<1||amount>1000000)throw Error('积分数量须为 1～1,000,000 的整数。');const subtract=$('#user-credit-direction').value==='subtract';if(subtract&&amount>c.available)throw Error('最多可减少 '+number(c.available)+' 积分，不能扣减任务已预占的积分。');prepare('credits',{delta:subtract?-amount:amount,reason:readReason('user-credit-reason')},(subtract?'减少':'增加')+' '+number(amount)+' 科研积分',[['当前可用',number(c.available)],['调整后可用',number(c.available+(subtract?-amount:amount))]]);}catch(failure){error(failure.message);}};
  $('#user-membership-form').onsubmit=event=>{event.preventDefault();try{const action=$('#user-member-action').value,payload={action,reason:readReason('user-member-reason')};let selected;if(action==='grant'){selected=data.membershipProducts.find(row=>row.id===$('#user-member-product').value);if(!selected)throw Error('请先配置一个有有效期与服务额度的会员方案。');payload.productId=selected.id;}else{selected=grants.find(row=>row.id===$('#user-member-grant').value);if(!selected)throw Error('请先选择需要调整的会员。');payload.grantId=selected.id;}if(action!=='revoke'){const raw=$('#user-member-expiry').value,expiry=new Date(raw);if(!raw||!Number.isFinite(expiry.getTime())||expiry.getTime()<=Date.now())throw Error('请选择晚于当前时间的到期时间。');payload.expiresAt=expiry.toISOString();}prepare('membership',payload,action==='grant'?'发放会员':action==='update'?'调整会员到期时间':'撤销会员',[['会员方案',selected.title],['到期时间',action==='revoke'?'确认后立即停用':date(payload.expiresAt)]]);}catch(failure){error(failure.message);}};
  $('#user-status-form')?.addEventListener('submit',event=>{event.preventDefault();try{const status=$('#user-status-value').value;if(status===u.status)throw Error('账号已经处于所选状态，无需重复调整。');prepare('status',{status,reason:readReason('user-status-reason')},status==='banned'?'封禁账号':'解封账号',[['调整后状态',status==='banned'?'已封禁，退出所有登录':'正常使用，可重新登录']]);}catch(failure){error(failure.message);}});
  root.scrollTop=0;
  if(review)showReview();
 }
 function readReason(id){const value=$(('#'+id)).value.trim();if(!value||value.length>500)throw Error('请填写调整原因，最多 500 字。');return value;}
 function memberFields(reset=false){
  const action=$('#user-member-action').value,grant=action!=='grant';$('#user-member-product-field').hidden=grant;$('#user-member-grant-field').hidden=!grant;$('#user-member-expiry-field').hidden=action==='revoke';
  const selected=grant?data.memberships.find(row=>row.id===$('#user-member-grant').value):data.membershipProducts.find(row=>row.id===$('#user-member-product').value);
  if(reset)$('#user-member-expiry').value=localDate(grant?selected?.expiresAt:new Date(Date.now()+(selected?.durationDays||30)*86400000).toISOString());
  $('#user-member-note').textContent=action==='grant'?'发放该方案当前配置的总次数，改变到期时间不会增加服务次数。':action==='update'?'仅调整有效期，保留已用次数；缩短时间不会退回已结算的积分。':'撤销后不能再使用该会员，已完成的任务与原购买记录会保留。';
 }
 function prepare(kind,input,label,summary){
  if(busy||review)return;
  error('');const commandId=win.crypto.randomUUID();review={kind,payload:{commandId,version:data.user.version,...input},label,summary,uncertain:false};
  if(!persistCommand(review)){review=null;throw Error('暂时无法保存本次操作标识，请检查浏览器存储后重试。');}
  showReview();
 }
 function showReview(){
  if(!live()||!review)return;
  root.querySelectorAll('form input,form select,form textarea,form button').forEach(node=>node.disabled=true);
  const box=$('#user-management-review');box.innerHTML=`<section class="user-change-review" aria-label="确认用户调整"><span>操作核对</span><h3>${esc(review.label||'继续核对上次账户调整')}</h3><p>用户：<b>${esc(title())}</b></p><dl>${(review.summary||[]).map(([label,value])=>`<div><dt>${esc(label)}</dt><dd>${esc(value)}</dd></div>`).join('')}<div><dt>调整原因</dt><dd>${esc(review.payload.reason)}</dd></div></dl><p class="form-error" id="user-review-error" role="alert" hidden></p><div class="dialog-actions"><button class="button" type="button" data-user-cancel-review ${review.uncertain?'disabled':''}>返回修改</button><button class="button ${review.kind==='status'&&review.payload.status==='banned'?'danger-solid':'primary'}" type="button" data-user-confirm>确认调整</button></div></section>`;
  $('[data-user-cancel-review]').onclick=()=>{if(busy||review?.uncertain)return;review=null;persistCommand(null);render();};
  $('[data-user-confirm]').onclick=()=>void submit();
  box.scrollIntoView?.({block:'nearest',behavior:'instant'});
 }
 async function submit(){
  if(!live()||busy||!review)return;
  busy=true;const command=review;const confirm=$('[data-user-confirm]');confirm.disabled=true;confirm.textContent='正在保存…';$('[data-user-cancel-review]').disabled=true;$('#user-reload-detail').disabled=true;
  try{const value=await request(path+'/'+command.kind,command.payload);if(!live())return;if(!valid(value))throw Error('返回的用户资料不完整，请刷新核对本次操作结果。');data=value;review=null;persistCommand(null);render();toast?.('用户资料已更新，操作记录已保存。');onChanged?.(value.user);}
  catch(failure){if(!live())return;const area=$('#user-review-error');area.hidden=false;area.textContent=failure.message;if(failure.status===409){area.textContent+=' 请刷新用户资料后重新核对。';confirm.disabled=true;confirm.textContent='请先刷新用户资料';review=null;persistCommand(null);}else if(failure.status>=400&&failure.status<500){confirm.disabled=false;confirm.textContent='重试本次调整';$('[data-user-cancel-review]').disabled=false;}else{command.uncertain=true;persistCommand(command);confirm.disabled=false;confirm.textContent='重试本次调整';area.textContent+=' 本次结果尚未确认，请重试同一次操作，避免重复调整。';}}
  finally{busy=false;if(live()&&$('#user-reload-detail'))$('#user-reload-detail').disabled=false;}
 }
 async function load(){
  if(!live()||busy)return;const sequence=++loadSequence;root.innerHTML='<div class="loading-state" role="status"><span class="spinner"></span>正在读取用户会员与积分…</div>';
  try{const value=await request(path+'/manage');if(!live()||sequence!==loadSequence)return;if(!valid(value))throw Error('用户资料不完整，请刷新后重试。');data=value;review=restoreCommand();if(!review)persistCommand(null);render();}
  catch(failure){if(!live()||sequence!==loadSequence)return;root.innerHTML=`<p class="form-error" role="alert">${esc(failure.message)}</p><button class="button" id="user-detail-retry">重新读取</button>`;$('#user-detail-retry').onclick=()=>void load();}
 }
 void load();
 return {reload:load};
}
